INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('drp3e74ghq627a93ridrp3e7kz3n62fq', '2026-Q2', 'Jun–Jul/2026 (T2)', '2026-06-26T02:46'::timestamptz, 'Thiago Pugliesi Garcia', 'thiago pugliesi garcia', 'PHARUS', 'Gustavo Papeschi Mariano', 8.0, 'Neutro', 10.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Entendi o método, mas ainda não implementei o suficiente', 'Tivemos muitos problemas de resposta, suporte e atendimento no início. Isto só foi solucionado meses após iniciarmos nosso contrato, e só se melhorou com a chegada do Gustavo Papeschi como nosso atual consultor.  Antes do Gustavo a impressão era de um serviço amador e muitooo abaixo do esperado.', 'Acredito que neste momento estamos caminhando pra isto, graças ao Gustavo que tem se esforçado e dedicado ao máximo pra tirar a impressão ruim do início de nossa parceria com a quarta via. Outro ponto importante é a melhor informação e opções de recursos visando os clientes em situação de não residente fiscal.', NULL, 'Ver o retorno e sentir o processo andar.', 'Temos um sentimento misto, acreditamos na filosofia, desejamos implementar, mas o início da relação devido as pessoas que foram designadas para nos atender nos deixou uma sensação ruim que ainda persiste em alguns momentos. Nossa relação hoje é muito boa com nosso assessor o que nos traz a esperança que o projeto funciona.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'drp3e74ghq627a93ridrp3e7kz3n62fq', 'base mecanismos (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('9b734i8i0x2vu2rj9b730kip5z57gk7x', '2026-Q2', 'Jun–Jul/2026 (T2)', '2026-06-26T09:25'::timestamptz, 'Leonardo Franchini Vinhola', 'leonardo franchini vinhola', 'PHARUS', 'Rodrigo Lunardi', 10.0, 'Promotor', 10.0, NULL, NULL, NULL, NULL, NULL, 'Totalmente no caminho', 'Tenho clareza e estou executando com consistência', 'A estrutura do programa é muito sólida, consolida conceitos diferentes de uma forma clara e concisa, permitindo ao participante entender melhor o que fazer. Além disso, o acompanhamento de perto do Engenheiro Patrimonial tanto traz luz às principais dúvidas, quanto "obriga" o participante à seguir o combinado, evitando distrações e colaborando para o atingimento das metas.', NULL, 'Engenheiro Patrimonial, acompanhamento constante. Estrutura sólida do programa (fundamentos em que o programa se apoia).', 'Na prática, continuar o bom trabalho, conforme o tempo andar e meus objetivos macro forem sendo atingidos, pretendo ser elegível a fazer parte do Davos se houver convite.', 'Sem mais comentários.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', '9b734i8i0x2vu2rj9b730kip5z57gk7x', 'base mecanismos (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXC